const clean = v => String(v ?? '').trim().replace(/\s+/g, ' ');
const normEmail = v => clean(v).toLowerCase();
const normPhone = v => { const raw = clean(v); if (!raw) return ''; const digits = raw.replace(/\D/g, ''); return raw.startsWith('+') ? '+' + digits : digits; };
const input = $input.all().map(i => i.json.body ?? i.json);
return input.map(raw => {
  const eventId = clean(raw.event_id);
  const name = clean(raw.name);
  const email = normEmail(raw.email);
  const phone = normPhone(raw.phone);
  const contact = email || phone;
  const source = clean(raw.source);
  const service = clean(raw.service);
  const message = clean(raw.message);
  const desiredDate = clean(raw.desired_date);
  const budget = clean(raw.budget);
  const missing = [];
  if (!eventId) missing.push('event_id');
  if (!name) missing.push('name');
  if (!contact) missing.push('email_or_phone');
  if (missing.length) {
    return {json:{ok:false,status:'validation_failed',missing_fields:missing,autonomous_send:false,next_step:'fix_input_before_processing'}};
  }
  const summary = [
    `Name: ${name}`,
    `Contact: ${contact}`,
    `Source: ${source || 'N/A'}`,
    `Service: ${service || 'N/A'}`,
    `Desired date: ${desiredDate || 'N/A'}`,
    `Budget: ${budget || 'N/A'}`,
    `Message: ${message || 'N/A'}`
  ].join('\n');
  const replyDraft = `${name}, thanks for your enquiry. We have received your details and will review them before confirming the next step. This is a draft for human review and has not been sent.`;
  return {json:{
    ok:true,
    status:'prepared_for_human_review',
    event_id:eventId,
    identity:{email,phone},
    normalized:{name,source,service,message,desired_date:desiredDate,budget},
    missing_fields:[],
    summary,
    reply_draft:replyDraft,
    next_step:'human_review',
    autonomous_send:false
  }};
});
